package com.securebiz.notification.api;import com.securebiz.notification.api.NotificationDtos.NotificationResponse;import com.securebiz.notification.repository.NotificationRepository;import com.securebiz.shared.api.BusinessException;import com.securebiz.shared.security.CurrentActor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationRepository repo;public NotificationController(NotificationRepository repo){this.repo=repo;}@GetMapping@PreAuthorize("hasAuthority('notification.view')")@Transactional(readOnly=true)List<NotificationResponse>list(){return repo.list(CurrentActor.userId());}@PostMapping("/{id}/read")@PreAuthorize("hasAuthority('notification.view')")@Transactional ResponseEntity<Void>read(@PathVariable UUID id){if(repo.read(id,CurrentActor.userId())==0)throw new BusinessException(HttpStatus.NOT_FOUND,"NOTIFICATION_NOT_FOUND","Notification not found");return ResponseEntity.noContent().build();}}
